import { createReadStream, createWriteStream } from 'node:fs';
import { access, mkdir, rm } from 'node:fs/promises';
import path from 'node:path';
import type { Readable, Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';

/**
 * Where attachment bytes live. Keys are generated by the server ("<orgId>/<uuid>") and never derived
 * from user input. In production this interface is implemented over S3-compatible object storage.
 */
export interface StorageDriver {
  /** Streams `source` through `transforms` into the object. Errors from any stage reject. */
  write(key: string, source: Readable, ...transforms: Transform[]): Promise<void>;
  /** Resolves to null if the object does not exist. */
  read(key: string): Promise<Readable | null>;
  remove(key: string): Promise<void>;
}

const KEY_PATTERN = /^[0-9a-f-]{36}\/[0-9a-f-]{36}$/;

export class LocalDiskStorage implements StorageDriver {
  constructor(private readonly root: string) {}

  private resolve(key: string): string {
    // Keys are generated server-side, but check anyway so a bug can never escape the storage root.
    if (!KEY_PATTERN.test(key)) throw new Error('invalid storage key');
    return path.join(this.root, key);
  }

  async write(key: string, source: Readable, ...transforms: Transform[]): Promise<void> {
    const target = this.resolve(key);
    await mkdir(path.dirname(target), { recursive: true });
    // 'wx' fails if the file exists, so a key collision can never overwrite another file.
    await pipeline([source, ...transforms, createWriteStream(target, { flags: 'wx', mode: 0o640 })]);
  }

  async read(key: string): Promise<Readable | null> {
    const file = this.resolve(key);
    try {
      await access(file);
    } catch {
      return null;
    }
    return createReadStream(file);
  }

  async remove(key: string): Promise<void> {
    await rm(this.resolve(key), { force: true });
  }
}
